def main():
    d = json.load(open(NEWS, encoding='utf-8'))
    exist = {x['title'][:60] for x in d}
    add = [x for x in ITEMS if x['title'][:60] not in exist]
    d.extend(add)
    json.dump(d, open(NEWS, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print(f'news-2026-09-17.json: +{len(add)} 条 → 共 {len(d)} 条')
    for x in add:
        print('  -', x['track'], x['title'][:52])


if __name__ == '__main__':
    main()
